'use strict';
// The golden fixtures are shared with the Rust core (crates/pime-core/tests/parity.rs). They are generated by
// tests/gen-fixtures.js from this JavaScript engine; this test fails when the engine drifts from them, so a
// behaviour change has to be an explicit fixture regeneration that the Rust side must follow.
const {test} = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const {spawnSync} = require('node:child_process');
const {core} = require('./helpers');
const L = core('languages'), V = core('validators'), x86 = core('x86'), secrets = core('secrets');

const dir = path.join(__dirname, '..', 'fixtures');
const load = name => JSON.parse(fs.readFileSync(path.join(dir, name), 'utf8'));

test('PARITY predict fixtures (94 cases) match the JS engine', () => {
  const f = load('predict-cases.json');
  assert.ok(f.cases.length >= 90);
  for (const c of f.cases) {
    const got = L.predict({profile: c.profile, prefix: c.prefix, before: c.before, after: c.after, dialect: c.dialect, limit: f.limit}).map(x => ({id: x.id, kind: x.kind, source: x.source, validation: x.validation, text: x.text, match: x.match}));
    assert.deepEqual(got, c.expect, `${c.profile}/${JSON.stringify(c.prefix)}`);
  }
});
test('PARITY validate fixtures match the JS validators', () => {
  for (const c of load('validate-cases.json').cases) {
    const r = V.validateSource(c.profile, c.text, c.dialect);
    assert.deepEqual({ok: r.ok, level: r.level, codes: r.issues.map(i => i.code), lines: r.issues.map(i => i.line)}, c.expect, `${c.profile}: ${JSON.stringify(c.text).slice(0, 50)}`);
  }
});
test('PARITY x86 vectors match the JS encoder (and unsupported forms never yield bytes)', () => {
  for (const c of load('x86-vectors.json').cases) {
    const r = x86.encode(c.asm);
    if (c.ok) assert.equal(r.hex, c.hex, c.asm); else { assert.equal(r.ok, false, c.asm); assert.equal(r.code, c.code, c.asm); assert.equal(r.hex, undefined); }
  }
});
test('PARITY resolve fixtures match the JS language resolver', () => {
  for (const c of load('resolve-cases.json').cases) {
    const r = L.resolveLanguage(c.ctx, c.current, c.lock);
    assert.deepEqual({language: r.language, reason: r.reason, changed: r.changed, uncertain: !!r.uncertain, suggestion: r.suggestion || null, dialectHints: r.dialectHints}, c.expect, JSON.stringify(c.ctx));
  }
});
test('PARITY secret fixtures match the JS scanner', () => {
  for (const c of load('secret-cases.json').cases) {
    const r = secrets.scan(c.text, {fileName: c.fileName});
    assert.deepEqual({highest: r.highest, sensitiveFile: r.sensitiveFile, findings: r.findings.map(x => ({kind: x.kind, severity: x.severity, line: x.line}))}, c.expect);
  }
});
test('PARITY fixtures are exactly what the generator produces (no hand edits)', () => {
  const gen = path.join(__dirname, '..', 'gen-fixtures.js');
  const r = spawnSync(process.execPath, [gen, '--check'], {encoding: 'utf8'});
  assert.equal(r.status, 0, r.stderr + r.stdout);
});
